// Own: zzOWN.com - Own Fast. Work Faster.  | Ema: zzown.com@gmail.com
// Des: Tests for nt-vend-deco: POST shape, results parsing, bad replies
// Flo: build request > canned JSON replies > assert Rsp
// I/O: canned bodies > pass or fail
// Run: zig build test
// ===================================================================
const std = @import("std"); const base = @import("nt-vend-base.zig"); const deco = @import("nt-vend-deco.zig");
const Fake = struct { seen: ?base.Http = null, code: u16, body: []const u8, pub fn send(self: *Fake) base.Send { return .{ .ctx = self, .call = callz }; } fn callz(ctx: *anyopaque, gpaz: std.mem.Allocator, _: std.Io, http: base.Http) anyerror!base.Back { const self: *Fake = @ptrCast(@alignCast(ctx)); self.seen = http; return .{ .code = self.code, .body = try gpaz.dupe(u8, self.body) }; } };
test "plain has no headless, render adds it; Basic auth and JSON POST" { var aren = std.heap.ArenaAllocator.init(std.testing.allocator); defer aren.deinit(); const allo = aren.allocator(); const one = try deco.reqBuild(allo, "TOKEN", .{ .urlz = "https://a.com/x", .mode = .plain }); try std.testing.expect(one.post); try std.testing.expectEqualStrings("Basic TOKEN", one.auth); try std.testing.expectEqualStrings("{\"url\":\"https://a.com/x\"}", one.body); const two = try deco.reqBuild(allo, "TOKEN", .{ .urlz = "https://a.com/x", .mode = .rend }); try std.testing.expectEqualStrings("{\"url\":\"https://a.com/x\",\"headless\":\"html\"}", two.body); }
test "results[0] content and status_code are read, credits charged" { var aren = std.heap.ArenaAllocator.init(std.testing.allocator); defer aren.deinit(); var fak: Fake = .{ .code = 200, .body = "{\"results\":[{\"content\":\"<html>hi</html>\",\"status_code\":200}]}" }; const rsp = try deco.call(aren.allocator(), std.testing.allocator, std.testing.io, fak.send(), "TOKEN", .{ .urlz = "https://a.com/", .mode = .rend }); try std.testing.expectEqual(@as(u16, 200), rsp.code); try std.testing.expectEqualStrings("<html>hi</html>", rsp.body); try std.testing.expectEqual(@as(u32, 2), rsp.cred); }
test "a vendor 200 wrapping a target 403 is a block, uncharged" { var aren = std.heap.ArenaAllocator.init(std.testing.allocator); defer aren.deinit(); var fak: Fake = .{ .code = 200, .body = "{\"results\":[{\"content\":\"denied\",\"status_code\":403}]}" }; const rsp = try deco.call(aren.allocator(), std.testing.allocator, std.testing.io, fak.send(), "TOKEN", .{ .urlz = "https://a.com/", .mode = .plain }); try std.testing.expectEqual(@as(u16, 403), rsp.code); try std.testing.expectEqual(@as(u32, 0), rsp.cred); }
test "garbage replies become badresp, never a crash" { var aren = std.heap.ArenaAllocator.init(std.testing.allocator); defer aren.deinit(); const bads = [_][]const u8{ "", "not json", "[]", "{}", "{\"results\":[]}", "{\"results\":[1]}", "{\"results\":[{\"content\":5}]}" }; for (bads) |bad| { var fak: Fake = .{ .code = 200, .body = bad }; const rsp = try deco.call(aren.allocator(), std.testing.allocator, std.testing.io, fak.send(), "TOKEN", .{ .urlz = "https://a.com/", .mode = .plain }); try std.testing.expectEqualStrings("badresp", rsp.errz); try std.testing.expectEqual(@as(u32, 0), rsp.cred); } }
